=== FILE: skid_buffer.v ===
// skid_buffer.v
// Register slice (skid buffer) for one valid/ready stream.
// Implements microarchitecture.md (sections 2-4) for interface_spec.md.
// Every output is a flop or the inverse of one; inputs reach only next state.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats, only while m_valid is high.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // s_ready is the inverse of a flop.
    assign s_ready = !skid_valid;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat is accepted on this edge.
    wire s_fire = s_valid && s_ready;

    // Next state of the control bits (microarchitecture section 3).
    reg m_valid_d;
    reg skid_valid_d;
    always @* begin
        m_valid_d    = m_valid;
        skid_valid_d = skid_valid;
        if (m_free) begin
            // Load the skid beat if there is one, else the input (if valid).
            m_valid_d    = skid_valid || s_valid;
            skid_valid_d = 1'b0;
        end else if (s_fire) begin
            // Output stalled and a beat accepted: it goes to the skid register.
            skid_valid_d = 1'b1;
        end
    end

    // Data load enables and the single input multiplexer.
    wire             m_load    = m_free;
    wire             skid_load = !m_free && s_fire;
    wire [WIDTH-1:0] m_data_d  = skid_valid ? skid_data : s_data;

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (undefined while their valid bit is low).
    always @(posedge clk) begin
        if (m_load)
            m_data <= m_data_d;
        if (skid_load)
            skid_data <= s_data;
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Port-level queue model of up to two beats, moved only by handshakes.
    // Nothing is assumed about the sender or the receiver.
    // ------------------------------------------------------------------
    reg             f_past_valid = 1'b0;
    reg [1:0]       f_count;
    reg [WIDTH-1:0] f_q0;
    reg [WIDTH-1:0] f_q1;
    reg             f_was_full;
    reg [1:0]       f_streak;

    wire f_in  = s_valid && s_ready;
    wire f_out = m_valid && m_ready;

    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    always @(posedge clk) begin
        if (!rst_n)
            f_count <= 2'd0;
        else
            f_count <= f_count + {1'b0, f_in} - {1'b0, f_out};
    end

    always @(posedge clk) begin
        if (f_out) begin
            f_q0 <= f_q1;
            if (f_in) begin
                if (f_count == 2'd1)
                    f_q0 <= s_data;
                else
                    f_q1 <= s_data;
            end
        end else if (f_in) begin
            if (f_count == 2'd0)
                f_q0 <= s_data;
            else
                f_q1 <= s_data;
        end
    end

    // The ports behave as a queue of up to two beats.
    always @(*)
        if (f_past_valid) begin
            assert(f_count <= 2'd2);
            assert(m_valid == (f_count != 2'd0));
            assert(s_ready == (f_count != 2'd2));
            if (f_count != 2'd0)
                assert(m_data == f_q0);
            if (f_count == 2'd2)
                assert(skid_data == f_q1);
        end

    // A beat offered and not taken stays offered with the same data.
    always @(posedge clk)
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
            assert(m_valid);
            assert(m_data == $past(m_data));
        end

    // Cover bookkeeping.
    always @(posedge clk) begin
        if (!rst_n) begin
            f_was_full <= 1'b0;
            f_streak   <= 2'd0;
        end else begin
            if (skid_valid)
                f_was_full <= 1'b1;
            if (f_in && f_out) begin
                if (f_streak != 2'd3)
                    f_streak <= f_streak + 2'd1;
            end else begin
                f_streak <= 2'd0;
            end
        end
    end

    always @(*)
        if (f_past_valid && rst_n) begin
            cover(m_valid && !m_ready);      // a stall
            cover(skid_valid);               // a full slice
            cover(f_was_full && !m_valid);   // a drain after full
            cover(f_streak == 2'd3);         // full throughput, three edges
        end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: skid_buffer_tb.v ===
// skid_buffer_tb.v
// Self-checking testbench for skid_buffer: lanes at WIDTH 8 and WIDTH 1,
// driven with the same stimulus and checked against one queue model.

`define SB_CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error("skid_buffer_tb cycle %0d: %0s", cycle, msg); end end

module skid_buffer_tb;

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        s_valid = 1'b0;
    reg  [7:0] s_data  = 8'h00;
    reg        m_ready = 1'b0;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire       m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    always #5 clk = ~clk;

    // ---------------- model and bookkeeping ----------------
    reg  [7:0]  sbq [0:15];
    reg  [31:0] wr_ptr;
    reg  [31:0] rd_ptr;
    reg  [31:0] held;
    integer     passed;
    integer     failed;
    integer     cycle;
    integer     n_in;
    integer     n_out;
    integer     dropped;
    integer     base_in;
    integer     base_out;
    integer     cov_full;
    integer     cov_stall;
    integer     cov_both;
    integer     i;
    integer     rc;
    reg         checking;
    reg         prev_stall;
    reg  [7:0]  prev_data8;
    reg         prev_data1;
    reg         in_fire;
    reg         out_fire;
    reg         rn_cap;
    reg         mv_cap;
    reg         mr_cap;
    reg  [7:0]  sd_cap;
    reg         snap_sr8;
    reg         snap_mv8;
    reg  [7:0]  snap_md8;
    reg         snap_sr1;
    reg         snap_mv1;
    reg         snap_md1;
    reg  [31:0] rng;
    reg  [8*64-1:0] nonce;

    // Compare the outputs of both lanes with the model (before an edge).
    task check_outputs;
        begin
            held = wr_ptr - rd_ptr;
            `SB_CHECK(held <= 32'd2, "model holds more than two beats")
            `SB_CHECK(m_valid8 === (held != 32'd0), "m_valid (WIDTH 8) does not match the beats held")
            `SB_CHECK(s_ready8 === (held < 32'd2), "s_ready (WIDTH 8) does not match the beats held")
            `SB_CHECK(m_valid1 === (held != 32'd0), "m_valid (WIDTH 1) does not match the beats held")
            `SB_CHECK(s_ready1 === (held < 32'd2), "s_ready (WIDTH 1) does not match the beats held")
            if (held != 32'd0) begin
                `SB_CHECK(m_data8 === sbq[rd_ptr[3:0]], "m_data (WIDTH 8) is not the oldest beat held")
                `SB_CHECK(m_data1 === sbq[rd_ptr[3:0]][0], "m_data (WIDTH 1) is not the oldest beat held")
            end
            if (prev_stall) begin
                `SB_CHECK(m_valid8 === 1'b1 && m_data8 === prev_data8, "a stalled beat (WIDTH 8) did not hold")
                `SB_CHECK(m_valid1 === 1'b1 && m_data1 === prev_data1, "a stalled beat (WIDTH 1) did not hold")
            end
            if (held == 32'd2)
                cov_full = cov_full + 1;
            if (m_valid8 === 1'b1 && m_ready === 1'b0)
                cov_stall = cov_stall + 1;
        end
    endtask

    // Advance the model with the handshakes sampled before the edge.
    task update_model;
        begin
            held = wr_ptr - rd_ptr;
            if (!rn_cap) begin
                dropped    = dropped + held;
                rd_ptr     = wr_ptr;
                prev_stall = 1'b0;
                checking   = 1'b1;
            end else begin
                if (in_fire && out_fire)
                    cov_both = cov_both + 1;
                if (out_fire) begin
                    rd_ptr = rd_ptr + 32'd1;
                    n_out  = n_out + 1;
                end
                if (in_fire) begin
                    sbq[wr_ptr[3:0]] = sd_cap;
                    wr_ptr = wr_ptr + 32'd1;
                    n_in   = n_in + 1;
                end
                prev_stall = mv_cap && !mr_cap;
            end
            cycle = cycle + 1;
        end
    endtask

    // One clock cycle: drive inputs at the falling edge, check, probe the
    // ready path, then take the rising edge.
    task step(input sv, input [7:0] sd, input mr, input rn);
        begin
            @(negedge clk);
            rst_n   = rn;
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            #1;
            if (checking)
                check_outputs;
            snap_sr8 = s_ready8;
            snap_mv8 = m_valid8;
            snap_md8 = m_data8;
            snap_sr1 = s_ready1;
            snap_mv1 = m_valid1;
            snap_md1 = m_data1;
            // Flip the inputs inside the cycle: no output may follow them.
            s_valid = ~sv;
            m_ready = ~mr;
            s_data  = ~sd;
            #1;
            if (checking) begin
                `SB_CHECK(s_ready8 === snap_sr8 && s_ready1 === snap_sr1, "s_ready moved with m_ready or s_valid inside a cycle")
                `SB_CHECK(m_valid8 === snap_mv8 && m_valid1 === snap_mv1, "m_valid moved with an input inside a cycle")
                `SB_CHECK(m_data8 === snap_md8 && m_data1 === snap_md1, "m_data moved with an input inside a cycle")
            end
            s_valid = sv;
            m_ready = mr;
            s_data  = sd;
            #1;
            rn_cap     = rn;
            sd_cap     = sd;
            mr_cap     = mr;
            mv_cap     = m_valid8;
            in_fire    = sv && s_ready8;
            out_fire   = m_valid8 && mr;
            prev_data8 = m_data8;
            prev_data1 = m_data1;
            @(posedge clk);
            update_model;
        end
    endtask

    // Directed check of the outputs just after the last edge.
    task expect_out(input ev, input [7:0] ed, input esr);
        begin
            #2;
            `SB_CHECK(m_valid8 === ev && m_valid1 === ev, "directed: m_valid not as expected")
            `SB_CHECK(s_ready8 === esr && s_ready1 === esr, "directed: s_ready not as expected")
            if (ev) begin
                `SB_CHECK(m_data8 === ed && m_data1 === ed[0], "directed: m_data not as expected")
            end
        end
    endtask

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task run_random(input [7:0] vthr, input [7:0] rthr, input integer ncyc, input ren);
        integer k;
        reg     rv;
        reg     rr;
        reg     rrst;
        begin
            for (k = 0; k < ncyc; k = k + 1) begin
                next_rand;
                rv   = (rng[7:0] < vthr);
                rr   = (rng[15:8] < rthr);
                rrst = ren && (rng[31:24] == 8'hFF);
                step(rv, rng[23:16], rr, ~rrst);
            end
        end
    endtask

    initial begin
        passed     = 0;
        failed     = 0;
        cycle      = 0;
        n_in       = 0;
        n_out      = 0;
        dropped    = 0;
        base_in    = 0;
        base_out   = 0;
        cov_full   = 0;
        cov_stall  = 0;
        cov_both   = 0;
        wr_ptr     = 32'd0;
        rd_ptr     = 32'd0;
        held       = 32'd0;
        checking   = 1'b0;
        prev_stall = 1'b0;
        rng        = 32'h1234_5678;
        nonce      = 512'd0;
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        for (i = 0; i < 16; i = i + 1)
            sbq[i] = 8'h00;

        // 1. Reset values (a beat offered during reset is dropped).
        step(1'b0, 8'h00, 1'b0, 1'b0);
        step(1'b1, 8'h5A, 1'b0, 1'b0);
        expect_out(1'b0, 8'h00, 1'b1);

        // 2. One-cycle latency: accepted on edge E, offered after E.
        step(1'b1, 8'hA5, 1'b0, 1'b1);
        expect_out(1'b1, 8'hA5, 1'b1);
        step(1'b0, 8'h00, 1'b1, 1'b1);
        expect_out(1'b0, 8'h00, 1'b1);

        // 3. Full throughput: one in and one out on every edge.
        base_in  = n_in;
        base_out = n_out;
        for (i = 0; i < 64; i = i + 1) begin
            step(1'b1, i[7:0], 1'b1, 1'b1);
            if (i > 0) begin
                `SB_CHECK(in_fire === 1'b1 && out_fire === 1'b1, "full throughput: a bubble")
            end
        end
        `SB_CHECK(n_in - base_in == 64 && n_out - base_out == 63, "full throughput: beat counts")
        step(1'b0, 8'h00, 1'b1, 1'b1);
        expect_out(1'b0, 8'h00, 1'b1);

        // 4. Stall with one beat held (second accepted) and two (third refused).
        step(1'b1, 8'h11, 1'b0, 1'b1);
        expect_out(1'b1, 8'h11, 1'b1);
        step(1'b1, 8'h22, 1'b0, 1'b1);
        `SB_CHECK(in_fire === 1'b1, "stall: second beat not accepted")
        expect_out(1'b1, 8'h11, 1'b0);
        step(1'b1, 8'h33, 1'b0, 1'b1);
        `SB_CHECK(in_fire === 1'b0, "stall: third beat accepted")
        expect_out(1'b1, 8'h11, 1'b0);
        step(1'b0, 8'hEE, 1'b0, 1'b1);
        expect_out(1'b1, 8'h11, 1'b0);
        step(1'b1, 8'h33, 1'b0, 1'b1);
        expect_out(1'b1, 8'h11, 1'b0);
        // Ready rises: every beat out in order and once.
        step(1'b1, 8'h33, 1'b1, 1'b1);
        `SB_CHECK(out_fire === 1'b1 && in_fire === 1'b0, "stall release: first edge")
        expect_out(1'b1, 8'h22, 1'b1);
        step(1'b1, 8'h33, 1'b1, 1'b1);
        `SB_CHECK(out_fire === 1'b1 && in_fire === 1'b1, "stall release: second edge")
        expect_out(1'b1, 8'h33, 1'b1);
        step(1'b0, 8'h00, 1'b1, 1'b1);
        expect_out(1'b0, 8'h00, 1'b1);

        // 5. Reset with two beats held, then with one.
        step(1'b1, 8'h44, 1'b0, 1'b1);
        step(1'b1, 8'h55, 1'b0, 1'b1);
        expect_out(1'b1, 8'h44, 1'b0);
        step(1'b1, 8'h66, 1'b0, 1'b0);
        expect_out(1'b0, 8'h00, 1'b1);
        step(1'b1, 8'h77, 1'b0, 1'b1);
        expect_out(1'b1, 8'h77, 1'b1);
        step(1'b0, 8'h00, 1'b0, 1'b0);
        expect_out(1'b0, 8'h00, 1'b1);
        step(1'b1, 8'h88, 1'b1, 1'b1);
        expect_out(1'b1, 8'h88, 1'b1);
        step(1'b0, 8'h00, 1'b1, 1'b1);
        expect_out(1'b0, 8'h00, 1'b1);

        // 6. Random traffic against the model, with reset during traffic.
        cov_full  = 0;
        cov_stall = 0;
        cov_both  = 0;
        run_random(8'd128, 8'd128, 1000, 1'b0);
        run_random(8'd230, 8'd70, 800, 1'b0);
        step(1'b1, 8'h99, 1'b1, 1'b0);
        run_random(8'd70, 8'd230, 800, 1'b0);
        run_random(8'd160, 8'd160, 1500, 1'b1);

        // 7. Drain.
        for (i = 0; i < 4; i = i + 1)
            step(1'b0, 8'h00, 1'b1, 1'b1);
        expect_out(1'b0, 8'h00, 1'b1);
        `SB_CHECK(wr_ptr == rd_ptr, "drain: model still holds beats")
        `SB_CHECK(n_in == n_out + dropped, "every accepted beat left once or was dropped by reset")
        `SB_CHECK(cov_full > 0 && cov_stall > 0 && cov_both > 0, "random traffic missed a coverage goal")

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`undef SB_CHECK
=== END FILE ===
